import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: parse tenant context from JWT (simplified)
function tenantContext(req, res, next) {
  const tenantId = req.headers['x-tenant-id'];
  const apiKey = req.headers['x-api-key'];
  if (!tenantId || !apiKey) return res.status(401).json({ error: 'missing credentials' });
  req.tenantId = tenantId;
  req.apiKey = apiKey;
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', tenantContext, async (req, res) => {
  try {
    const { category, status, sort_by, direction, limit } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Sort - validated against allowlist... or so we think
    const allowedSorts = ['name', 'created_at', 'category', 'status'];
    const sortCol = sort_by || 'created_at';
    const sortDir = direction === 'asc' ? 'ASC' : 'DESC';

    // BUG: sortCol checked but result not used; raw sort_by injected
    const isValid = allowedSorts.includes(sortCol);
    query += ` ORDER BY ${sort_by || 'created_at'} ${sortDir}`;

    // Limit
    const rowLimit = Math.min(parseInt(limit) || 50, 200);
    query += ` LIMIT ${rowLimit}`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', tenantContext, async (req, res) => {
  const { asset_ids, updates } = req.body;
  if (!Array.isArray(asset_ids) || asset_ids.length === 0) {
    return res.status(400).json({ error: 'asset_ids required' });
  }
  if (asset_ids.length > 100) {
    return res.status(400).json({ error: 'max 100 assets per batch' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const setClauses = [];
    const setParams = [req.tenantId];
    let idx = 2;

    for (const [key, value] of Object.entries(updates)) {
      if (['status', 'category', 'metadata'].includes(key)) {
        setClauses.push(`${key} = $${idx}`);
        setParams.push(value);
        idx++;
      }
    }

    if (setClauses.length === 0) {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'no valid fields' });
    }

    const placeholders = asset_ids.map((_, i) => `$${idx + i}`).join(',');
    const allParams = [...setParams, ...asset_ids];

    const updateQuery = `UPDATE assets SET ${setClauses.join(', ')}, updated_at = NOW()
                         WHERE tenant_id = $1 AND id IN (${placeholders})`;

    const result = await client.query(updateQuery, allParams);
    await client.query('COMMIT');
    res.json({ updated: result.rowCount });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'internal error' });
  } finally {
    client.release();
  }
});

